// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
import type { DirectoryUser } from '../core/evaluator.ts';
import type {
  ExplicitGrant,
  PermissionScope,
  RbacAction,
  RbacResourceType,
  ReportingRow,
  RoleBoundary,
} from '../core/rbac.ts';

export interface IdentitySnapshot {
  organization_id: string;
  users: DirectoryUser[];
  roles: RoleBoundary[];
  grants?: ExplicitGrant[];
  reporting?: ReportingRow[];
}

const PERMISSIONS = new Set<PermissionScope>([
  'All',
  'OrganizationRead',
  'OrganizationReadUpdate',
  'AssignedReadAll',
  'AssignedReadUpdateAll',
  'SelfCreatedAll',
  'DepartmentAssignedReadAll',
  'DepartmentAssignedReadUpdateAll',
  'BusinessUnitAssignedReadAll',
  'BusinessUnitAssignedReadUpdateAll',
  'ReporteeAssignedReadUpdateAll',
]);
const ACTIONS = new Set<RbacAction>(['read', 'write', 'delete', 'admin']);
// 'object' grants are platform shares keyed `<object type>:<object id>`.
const RESOURCES = new Set<RbacResourceType | 'object'>(['workflow', 'instance', 'directory', 'object']);
const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

export interface SnapshotValidation {
  snapshot?: IdentitySnapshot;
  issues: string[];
}

/** Validate the complete organization identity/RBAC projection before mutating any plane. */
export function validateIdentitySnapshot(value: unknown): SnapshotValidation {
  const issues: string[] = [];
  if (!isRecord(value)) return { issues: ['body must be a JSON object'] };

  const organization_id = typeof value.organization_id === 'string'
    ? value.organization_id.trim()
    : '';
  if (!organization_id) issues.push('organization_id must be a non-empty string');

  const users = Array.isArray(value.users) ? value.users as DirectoryUser[] : [];
  const roles = Array.isArray(value.roles) ? value.roles as RoleBoundary[] : [];
  const grants = value.grants === undefined
    ? []
    : Array.isArray(value.grants) ? value.grants as ExplicitGrant[] : [];
  const reporting = value.reporting === undefined
    ? []
    : Array.isArray(value.reporting) ? value.reporting as ReportingRow[] : [];
  if (!Array.isArray(value.users)) issues.push('users must be an array');
  if (!Array.isArray(value.roles)) issues.push('roles must be an array');
  if (value.grants !== undefined && !Array.isArray(value.grants)) issues.push('grants must be an array');
  if (value.reporting !== undefined && !Array.isArray(value.reporting)) issues.push('reporting must be an array');

  const userIds = new Set<string>();
  users.forEach((user, index) => {
    if (!isRecord(user)) {
      issues.push(`users[${index}] must be an object`);
      return;
    }
    if (typeof user.id !== 'string' || !user.id.trim()) {
      issues.push(`users[${index}].id must be a non-empty string`);
      return;
    }
    if (userIds.has(user.id)) issues.push(`users[${index}].id duplicates "${user.id}"`);
    userIds.add(user.id);
    if (user.organization_id !== undefined && user.organization_id !== organization_id)
      issues.push(`users[${index}].organization_id must match snapshot organization_id`);
    if (user.role !== undefined && typeof user.role !== 'string')
      issues.push(`users[${index}].role must be a string`);
    if (
      user.employment_status_active !== undefined &&
      typeof user.employment_status_active !== 'boolean'
    ) issues.push(`users[${index}].employment_status_active must be a boolean`);
    if (
      user.departments !== undefined &&
      (!Array.isArray(user.departments) || user.departments.some((d) => typeof d !== 'string'))
    ) issues.push(`users[${index}].departments must be an array of strings`);
    if (
      user.reporting_managers !== undefined &&
      (!Array.isArray(user.reporting_managers) ||
        user.reporting_managers.some((manager) => typeof manager !== 'string'))
    ) issues.push(`users[${index}].reporting_managers must be an array of user ids`);
  });

  const roleNames = new Set<string>();
  roles.forEach((role, index) => {
    if (!isRecord(role)) {
      issues.push(`roles[${index}] must be an object`);
      return;
    }
    if (typeof role.name !== 'string' || !role.name.trim()) {
      issues.push(`roles[${index}].name must be a non-empty string`);
      return;
    }
    if (roleNames.has(role.name)) issues.push(`roles[${index}].name duplicates "${role.name}"`);
    roleNames.add(role.name);
    if (!Array.isArray(role.permissions)) {
      issues.push(`roles[${index}].permissions must be an array`);
      return;
    }
    role.permissions.forEach((permission, permissionIndex) => {
      if (!isRecord(permission) || !PERMISSIONS.has(permission.permission as PermissionScope))
        issues.push(`roles[${index}].permissions[${permissionIndex}].permission is unsupported`);
      if (
        isRecord(permission) && permission.object_name !== undefined &&
        typeof permission.object_name !== 'string'
      ) issues.push(`roles[${index}].permissions[${permissionIndex}].object_name must be a string`);
    });
  });
  users.forEach((user, index) => {
    if (typeof user?.role === 'string' && !roleNames.has(user.role))
      issues.push(`users[${index}].role "${user.role}" is absent from roles`);
  });

  grants.forEach((grant, index) => {
    if (!isRecord(grant)) {
      issues.push(`grants[${index}] must be an object`);
      return;
    }
    if (typeof grant.user_id !== 'string' || !userIds.has(grant.user_id))
      issues.push(`grants[${index}].user_id must reference a snapshot user`);
    if (!RESOURCES.has(grant.resource_type as RbacResourceType))
      issues.push(`grants[${index}].resource_type is unsupported`);
    if (typeof grant.resource_id !== 'string' || !grant.resource_id)
      issues.push(`grants[${index}].resource_id must be a non-empty string`);
    if (!Array.isArray(grant.actions) || grant.actions.some((action) => !ACTIONS.has(action)))
      issues.push(`grants[${index}].actions contains an unsupported action`);
    if (grant.is_active !== undefined && typeof grant.is_active !== 'boolean')
      issues.push(`grants[${index}].is_active must be a boolean`);
    if (grant.expires_at !== undefined && (typeof grant.expires_at !== 'string' || Number.isNaN(Date.parse(grant.expires_at))))
      issues.push(`grants[${index}].expires_at must be an ISO timestamp`);
  });

  reporting.forEach((row, index) => {
    if (!isRecord(row)) {
      issues.push(`reporting[${index}] must be an object`);
      return;
    }
    if (typeof row.reporting_manager !== 'string' || !userIds.has(row.reporting_manager))
      issues.push(`reporting[${index}].reporting_manager must reference a snapshot user`);
    if (typeof row.reportee !== 'string' || !userIds.has(row.reportee))
      issues.push(`reporting[${index}].reportee must reference a snapshot user`);
    if (row.business_unit !== undefined && typeof row.business_unit !== 'string')
      issues.push(`reporting[${index}].business_unit must be a string`);
  });

  if (issues.length) return { issues };
  return {
    issues,
    snapshot: {
      organization_id,
      users: users.map((user) => ({ ...user, id: user.id.trim(), organization_id })),
      roles,
      grants,
      reporting,
    },
  };
}
